insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-ek-176","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The quantity of electricity $Q$ that flows in time $t$ at a steady current $I$ is","options":["$Q = It$","$Q = I/t$","$Q = t/I$","$Q = I + t$"],"answer_index":0,"explanation":"Current is charge per unit time, so charge is the product $It$ (amperes × seconds = coulombs).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-177","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrolysis of acidified water with inert electrodes liberates","options":["hydrogen at the cathode and oxygen at the anode, in a 2 : 1 volume ratio","oxygen at the cathode and hydrogen at the anode","only hydrogen, because oxygen stays dissolved","chlorine and sodium"],"answer_index":0,"explanation":"2 H$_2$O → 2 H$_2$ + O$_2$. Two moles of hydrogen appear for each mole of oxygen.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-178","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"During electrolysis the cathode is still defined as the electrode at which","options":["reduction occurs","oxidation occurs","the external battery is connected to earth","no ion can be discharged"],"answer_index":0,"explanation":"The cathode/anode labels follow the chemistry (reduction/oxidation), not the galvanic sign convention.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-179","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrochemical equivalent $Z$ of a substance equals","options":["molar mass divided by $nF$","molar mass multiplied by $nF$","$nF$ alone","cell constant divided by $\\kappa$"],"answer_index":0,"explanation":"$m = ZQ$ with $Z = M/(nF)$, so $Z$ is the mass liberated by one coulomb.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-180","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"To deposit one mole of aluminium from Al$^{3+}$ one must pass a charge of","options":["$3F$","$1F$","$2F$","$F/3$"],"answer_index":0,"explanation":"Each Al$^{3+}$ ion consumes three electrons, so 1 mol Al requires $3 \\times 96500\\ \\mathrm{C}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-181","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 1.0 A current sent for 965 s through aqueous AgNO$_3$ deposits silver (Ag = 108) amounting to","options":["$1.08\\ \\mathrm{g}$","$10.8\\ \\mathrm{g}$","$0.108\\ \\mathrm{g}$","$108\\ \\mathrm{g}$"],"answer_index":0,"explanation":"$m = (108/96500) \\times 1.0 \\times 965 = 1.08\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-182","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"How many coulombs are required to plate 0.50 mol of copper from Cu$^{2+}$?","options":["$96500\\ \\mathrm{C}$","$48250\\ \\mathrm{C}$","$193000\\ \\mathrm{C}$","$0.50\\ \\mathrm{C}$"],"answer_index":0,"explanation":"Each mole of Cu$^{2+}$ needs 2 mol electrons, so 0.50 mol needs $1.0\\,F = 96500\\ \\mathrm{C}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-183","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 2.0 A current flows for 965 s through acidified water. The STP volume of H$_2$ evolved is nearest","options":["$0.224\\ \\mathrm{L}$","$22.4\\ \\mathrm{L}$","$0.112\\ \\mathrm{L}$","$2.24\\ \\mathrm{L}$"],"answer_index":0,"explanation":"$Q = 1930\\ \\mathrm{C} = 0.020\\ \\mathrm{mol\\ e^-}$; $2\\,e^- \\to 1\\ \\mathrm{H_2}$, so $0.010\\ \\mathrm{mol} = 0.224\\ \\mathrm{L}$ at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-184","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"To deposit 0.216 g of Ag (Ag = 108) from AgNO$_3$ at 0.50 A, the time required is","options":["386 s","193 s","965 s","1930 s"],"answer_index":0,"explanation":"$Q = m \\times F / M = 0.216 \\times 96500 / 108 = 193\\ \\mathrm{C}$; $t = Q/I = 193/0.50 = 386\\ \\mathrm{s}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-185","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The same charge that deposits 1.08 g of silver will deposit, from Cu$^{2+}$ (Cu = 63.5), a copper mass of","options":["$0.318\\ \\mathrm{g}$","$1.08\\ \\mathrm{g}$","$0.635\\ \\mathrm{g}$","$2.16\\ \\mathrm{g}$"],"answer_index":0,"explanation":"Equivalents: $E(\\mathrm{Ag}) = 108$, $E(\\mathrm{Cu}) = 31.75$. $m_{\\mathrm{Cu}} = 1.08 \\times 31.75/108 = 0.318\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-186","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If 0.635 g of copper is plated from CuSO$_4$ in 1930 s, the steady current used was","options":["$1.0\\ \\mathrm{A}$","$0.50\\ \\mathrm{A}$","$2.0\\ \\mathrm{A}$","$0.10\\ \\mathrm{A}$"],"answer_index":0,"explanation":"$Q = (0.635 \\times 2 \\times 96500)/63.5 = 1930\\ \\mathrm{C}$; $I = Q/t = 1930/1930 = 1.0\\ \\mathrm{A}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-187","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A current of 2.0 A is passed for 30 min through molten Al$_2$O$_3$ (Al = 27). The mass of aluminium liberated is","options":["$0.336\\ \\mathrm{g}$","$1.008\\ \\mathrm{g}$","$0.112\\ \\mathrm{g}$","$9.00\\ \\mathrm{g}$"],"answer_index":0,"explanation":"$Q = 2.0 \\times 1800 = 3600\\ \\mathrm{C}$. $m = (27 \\times 3600)/(3 \\times 96500) \\approx 0.336\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-188","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The same current flows for the same time through AgNO$_3$ and then, separately, through AuCl$_3$ (Au = 197). If 1.08 g Ag is deposited, the gold deposited is nearest","options":["$0.657\\ \\mathrm{g}$","$1.97\\ \\mathrm{g}$","$0.328\\ \\mathrm{g}$","$3.00\\ \\mathrm{g}$"],"answer_index":0,"explanation":"Equal charge means equal equivalents: $m_{\\mathrm{Au}}/m_{\\mathrm{Ag}} = (197/3)/108$, so $m_{\\mathrm{Au}} = 1.08 \\times 197/(3 \\times 108) = 0.657\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-189","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A primary electrochemical cell is one that","options":["cannot be recharged by reversing the current","is recharged simply by plugging it into the mains","has no electrode at all","works only as an electrolytic cell"],"answer_index":0,"explanation":"Once the reductant and oxidant of a dry cell or button cell are spent, the cell is discarded.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-190","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A secondary cell differs from a primary cell in that it","options":["can be recharged because the cell reaction is reversible","never involves a redox change","has $E = 0$ at all times","must be discarded after a single use"],"answer_index":0,"explanation":"Lead–acid and Ni–Cd cells are secondary batteries: charging drives the discharge reaction backwards.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-191","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The common dry cell (Leclanché) uses a zinc cup as the anode and, as the cathode depolariser,","options":["manganese dioxide packed around a carbon rod","lead dioxide on a lead grid","porous platinum and hydrogen gas","solid sodium chloride only"],"answer_index":0,"explanation":"Zn is oxidised; MnO$_2$ is reduced at the carbon collector in the NH$_4$Cl / ZnCl$_2$ paste.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-192","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A hydrogen–oxygen fuel cell is designed so that the reactants are","options":["fed continuously, and the cell can run as long as fuel and oxidant are supplied","sealed once and for all inside a closed can","generated only by charging overnight","the same as those of a lead storage battery"],"answer_index":0,"explanation":"A fuel cell is a galvanic cell with continuous feeds; it is not a store of a finite charge like a battery.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-193","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Rusting of iron is classified as an electrochemical process because it involves","options":["local anodic oxidation of Fe and cathodic reduction of dissolved oxygen","a purely mechanical wearing away of the metal","melting of iron below 100 °C","photochemical cleavage of Fe–Fe bonds only"],"answer_index":0,"explanation":"Different surface spots act as tiny galvanic cells in the presence of a water film containing O$_2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-194","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ordinary rusting of iron requires, besides the metal itself,","options":["both moisture and oxygen","oxygen in a completely dry atmosphere only","a vacuum and ultraviolet light","solid NaCl with no water at all"],"answer_index":0,"explanation":"Water provides the ionic medium; oxygen is the cathodic oxidant. Dry iron in air rusts extremely slowly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-195","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"During discharge of a lead storage battery the electrolyte H$_2$SO$_4$ is consumed and the product deposited on both plates is","options":["lead(II) sulphate","lead metal only","lead dioxide only","elemental sulphur"],"answer_index":0,"explanation":"Pb + PbO$_2$ + 2 H$_2$SO$_4$ → 2 PbSO$_4$ + 2 H$_2$O. Charging reverses this reaction and regenerates acid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-196","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The only chemical product of a hydrogen–oxygen fuel cell operating with an alkaline or acid electrolyte is","options":["water","carbon dioxide","ammonia","hydrogen peroxide exclusively"],"answer_index":0,"explanation":"H$_2$ is oxidised and O$_2$ is reduced; their combination yields H$_2$O (and electrical work).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-197","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A buried iron pipeline is protected by attaching blocks of zinc or magnesium because those metals","options":["act as sacrificial anodes and corrode in preference to iron","raise the $E^\\circ$ of iron above that of oxygen","convert iron into stainless steel","absorb all moisture from the soil"],"answer_index":0,"explanation":"Zn and Mg are more active (more negative $E^\\circ$) than Fe, so they oxidise first and the pipeline becomes cathodic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-198","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"On a rusting iron surface the anodic half-change is Fe → Fe$^{2+}$ + 2 e$^-$. The matching cathodic process in a neutral water film is","options":["$\\mathrm{O_2 + 2H_2O + 4e^- \\rightarrow 4OH^-}$","$\\mathrm{Fe^{2+} + 2e^- \\rightarrow Fe}$","$\\mathrm{2H_2O \\rightarrow O_2 + 4H^+ + 4e^-}$","$\\mathrm{Zn^{2+} + 2e^- \\rightarrow Zn}$"],"answer_index":0,"explanation":"Dissolved oxygen is reduced to hydroxide. Fe$^{2+}$ and OH$^-$ then form rust (hydrated Fe$_2$O$_3$) after further oxidation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-199","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The instantaneous rate of consumption of a reactant A is written","options":["$-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","$+\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","$[\\mathrm{A}] \\times t$","$\\Delta G / \\Delta t$"],"answer_index":0,"explanation":"Concentration of a reactant falls, so the minus sign makes the rate a positive quantity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-200","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A rate law such as rate $= k[\\mathrm{A}]^x[\\mathrm{B}]^y$ must be established by","options":["experiment (initial rates or isolation methods)","copying the stoichiometric coefficients in every case","the equilibrium constant alone","the molecular mass of the product"],"answer_index":0,"explanation":"Orders $x$ and $y$ equal stoichiometric numbers only for an elementary step, not for an arbitrary overall equation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
